import{_ as p,a0 as l,w as o,s as d,ao as r,I as t,x as e,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"scanimage：從命令列掃描! | LCTT x X-CMD","titleTemplate":false,"description":"scanimage：從命令列掃描! | LCTT (202012) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"scanimage：從命令列掃描! | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"scanimage：從命令列掃描! | LCTT (202012) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202012/20200711 scanimage- scan from the command line","title":"scanimage：從命令列掃描!","tag":"202012","desc":""},"relativePath":"202012/20200711 scanimage- scan from the command line.md","filePath":"[post].md"}'),c={name:"202012/20200711 scanimage- scan from the command line.md"};function m(g,a,h,u,f,b){const s=l("Link");return o(),d("div",null,[a[15]||(a[15]=r(`<h1 id="scanimage-從命令列掃描" tabindex="-1">scanimage：從命令列掃描! <a class="header-anchor" href="#scanimage-從命令列掃描" aria-label="Permalink to “scanimage：從命令列掃描!”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202012/05/105822m30t6x66hz3hx6x3.jpg" alt=""></p><p>這又是一篇關於我很喜歡的一個命令列工具的文章。</p><p>昨晚，出於官僚原因，我需要掃描一些文檔。我以前從來沒有在 Linux 上使用過掃描儀，我擔心會花上好幾個小時才弄明白。我從使用 <code>gscan2pdf</code> 開始，但在用户界面上遇到了麻煩。我想同時掃描兩面（我知道我們的掃描儀支持），但無法使它工作。</p><h3 id="遇到-scanimage" tabindex="-1">遇到 scanimage！ <a class="header-anchor" href="#遇到-scanimage" aria-label="Permalink to “遇到 scanimage！”">​</a></h3><p><code>scanimage</code> 是一個命令列工具，在 <code>sane-utils</code> Debian 軟件包中。我想所有的 Linux 掃描工具都使用 <code>sane</code> （“scanner access now easy”） 庫，所以我猜測它和其他掃描軟件有類似的能力。在這裏，我不需要 OCR，所以我不打算談論 OCR。</p><h3 id="用-scanimage-l-得到你的掃描儀的名字" tabindex="-1">用 scanimage -L 得到你的掃描儀的名字 <a class="header-anchor" href="#用-scanimage-l-得到你的掃描儀的名字" aria-label="Permalink to “用 scanimage -L 得到你的掃描儀的名字”">​</a></h3><p><code>scanimage -L</code> 列出了你所有的掃描設備。</p><p>一開始我不能讓它工作，我有點沮喪，但事實證明，我把掃描儀連接到了我的電腦上，但沒有插上電源。</p><p>插上後，它馬上就能工作了。顯然我們的掃描儀叫 <code>fujitsu:ScanSnap S1500:2314</code>。萬歲！</p><h3 id="用-help-列出你的掃描儀選項" tabindex="-1">用 --help 列出你的掃描儀選項 <a class="header-anchor" href="#用-help-列出你的掃描儀選項" aria-label="Permalink to “用 --help 列出你的掃描儀選項”">​</a></h3><p>顯然每個掃描儀有不同的選項（有道理！），所以我運行這個命令來獲取我的掃描儀的選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>scanimage --help -d &#39;fujitsu:ScanSnap S1500:2314&#39;</span></span></code></pre></div><p>我發現我的掃描儀支持 <code>--source</code> 選項（我可以用它來啓用雙面掃描）和 <code>--resolution</code> 選項（我把它改為 150，以減少文件大小，使掃描更快）。</p><h3 id="scanimage-不支持輸出-pdf-文件-但你可以寫一個小腳本" tabindex="-1">scanimage 不支持輸出 PDF 文件（但你可以寫一個小腳本） <a class="header-anchor" href="#scanimage-不支持輸出-pdf-文件-但你可以寫一個小腳本" aria-label="Permalink to “scanimage 不支持輸出 PDF 文件（但你可以寫一個小腳本）”">​</a></h3><p>唯一的缺點是：我想要一個 PDF 格式的掃描文件，而 scanimage 似乎不支持 PDF 輸出。</p><p>所以我寫了這個 5 行的 shell 腳本在一個臨時文件夾中掃描一堆 PNG 文件，並將結果保存到 PDF 中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>set -e</span></span>
<span class="line"><span></span></span>
<span class="line"><span>DIR=\`mktemp -d\`</span></span>
<span class="line"><span>CUR=$PWD</span></span>
<span class="line"><span>cd $DIR</span></span>
<span class="line"><span>scanimage -b --format png  -d &#39;fujitsu:ScanSnap S1500:2314&#39; --source &#39;ADF Front&#39; --resolution 150</span></span>
<span class="line"><span>convert *.png $CUR/$1</span></span></code></pre></div><p>我像這樣運行腳本：<code>scan-single-sided output-file-to-save.pdf</code></p><p>你可能需要為你的掃描儀設置不同的 <code>-d</code> 和 <code>-source</code>。</p><h3 id="這真是太簡單了" tabindex="-1">這真是太簡單了! <a class="header-anchor" href="#這真是太簡單了" aria-label="Permalink to “這真是太簡單了!”">​</a></h3><p>我一直以為在 Linux 上使用打印機/掃描儀是一個噩夢，我真的很驚訝 <code>scanimage</code> 可以工作。我可以直接運行我的腳本 <code>scan-single-sided receipts.pdf</code>，它將掃描文檔並將其保存到 <code>receipts.pdf</code>！</p><hr>`,23)),t("p",null,[a[1]||(a[1]=e("via: ",-1)),n(s,{href:"https://jvns.ca/blog/2020/07/11/scanimage--scan-from-the-command-line/"},{default:i(()=>[...a[0]||(a[0]=[e("https://jvns.ca/blog/2020/07/11/scanimage--scan-from-the-command-line/",-1)])]),_:1})]),t("p",null,[a[6]||(a[6]=e("作者：",-1)),n(s,{href:"https://jvns.ca/"},{default:i(()=>[...a[2]||(a[2]=[e("Julia Evans",-1)])]),_:1}),a[7]||(a[7]=e(" 選題：",-1)),n(s,{href:"https://github.com/lujun9972"},{default:i(()=>[...a[3]||(a[3]=[e("lujun9972",-1)])]),_:1}),a[8]||(a[8]=e(" 譯者：",-1)),n(s,{href:"https://github.com/geekpi"},{default:i(()=>[...a[4]||(a[4]=[e("geekpi",-1)])]),_:1}),a[9]||(a[9]=e(" 校對：",-1)),n(s,{href:"https://github.com/wxy"},{default:i(()=>[...a[5]||(a[5]=[e("wxy",-1)])]),_:1})]),t("p",null,[a[12]||(a[12]=e("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[10]||(a[10]=[e("LCTT",-1)])]),_:1}),a[13]||(a[13]=e(" 原創編譯，",-1)),n(s,{href:"https://linux.cn/"},{default:i(()=>[...a[11]||(a[11]=[e("Linux中國",-1)])]),_:1}),a[14]||(a[14]=e(" 榮譽推出",-1))])])}const T=p(c,[["render",m]]);export{C as __pageData,T as default};
